steps.script:
var u = GameState.state.units['U_ALLARUS_CUSTODIANS_A_P2']
var c = Vector2.ZERO
for m in u.models:
	c += Vector2(m.position.x, m.position.y)
c /= u.models.size()
var d = Vector2(300, 1750) - c
for m in u.models:
	m.position = {'x': m.position.x + d.x, 'y': m.position.y + d.y}
tree.current_scene._recreate_unit_visuals()
return true

var pnl = tree.current_scene._ai_suggestion_panel
for r in range(3):
	for c in range(8):
		pnl._expanded['opt:%d:%d' % [r, c]] = true
pnl._render(false)
return pnl._rich.get_parsed_text().contains('Unit at risk: -')

var r = tree.current_scene._ai_suggestion_panel._rich
var t = r.get_parsed_text()
var line = t.substr(0, t.find('All options')).count('\n')
r.scroll_to_line(line)
return line > 0
